/**
 * Category (D73, D91 C1b; spec/02 §3.1b): content the user files himself. [tone] 1..6 = SebaroTheme.categories: a
 * 10 dp dot (or [icon], 20 dp) in that tone, 8 dp, then [text] in text; null = the word alone (an icon in text).
 * Never a fill, never text colour, never a state the app assigns. One TalkBack node.
 */
@Composable
fun SbCategory(
    text: String,
    modifier: Modifier = Modifier,
    tone: Int? = null,
    icon: ImageVector? = null,
    style: TextStyle = SebaroTheme.typography.body,
) {
    require(tone == null || tone in 1..6) { "SbCategory: tone 1 to 6 (D91 C1b), or null" }
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val color = tone?.let { n -> SebaroTheme.categories.first { it.number == n }.color }
    Row(
        modifier.semantics(mergeDescendants = true) { },
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(t.space.s2),
    ) {
        when {
            icon != null -> Icon(icon, contentDescription = null, tint = color ?: c.text, modifier = Modifier.size(t.size.iconMd))
            color != null -> Box(Modifier.size(10.dp).background(color, t.shapes.pill))   // the web's 10px dot
        }
        Text(text, style = style, color = c.text)
    }
}
